// StatusCodeColor selects the ANSI color for an HTTP status code and formats the log entry.
func (conf *LoggerConfig) StatusCodeColor(p *LogFormatterParams, isTerm bool, c *Context) string {
	path := p.Path
	if idx := strings.IndexByte(path, '?'); idx >= 0 {
		path = path[:idx]
	}
	for _, skip := range conf.SkipPaths {
		if skip == path {
			return ""
		}
	}

	var statusColor, methodColor, resetColor string
	if consoleColorMode == forceColor || (consoleColorMode == autoColor && isTerm) {
		code := p.StatusCode
		switch {
		case code >= http.StatusOK && code < http.StatusMultipleChoices:
			statusColor = green
		case code >= http.StatusMultipleChoices && code < http.StatusBadRequest:
			statusColor = white
		case code >= http.StatusBadRequest && code < http.StatusInternalServerError:
			statusColor = yellow
		default:
			statusColor = red
		}
		methodColor = p.MethodColor()
		resetColor = reset
	}

	latency := p.Latency
	if latency > time.Minute {
		latency = latency.Truncate(time.Second)
	}

	clientIP := p.ClientIP
	if c != nil {
		clientIP = c.ClientIP()
	}
